export type MediaType = "image" | "video" | "audio" | "document" | "other";

export interface GalleryItem {
  id: string;
  url: string;
  type: MediaType;
  name: string;
  size?: number;
  width?: number;
  height?: number;
  duration?: number;
  thumbnail?: string;
  createdAt?: Date;
  meta?: Record<string, unknown>;
}

export interface GalleryConfig {
  selectionMode?: "none" | "single" | "multi";
  sortable?: boolean;
  columns?: number;
  aspectRatio?: number;
  showNames?: boolean;
  showTypes?: boolean;
}

export interface GalleryContextValue {
  items: GalleryItem[];
  selectedIds: Set<string>;
  lightboxId: string | null;
  filter: MediaType | "all";
  config: GalleryConfig;

  select: (id: string, multi?: boolean) => void;
  deselect: (id: string) => void;
  selectAll: () => void;
  clearSelection: () => void;
  openLightbox: (id: string) => void;
  closeLightbox: () => void;
  nextLightbox: () => void;
  prevLightbox: () => void;
  setFilter: (f: MediaType | "all") => void;
  reorder: (items: GalleryItem[]) => void;
}

import * as React from "react";
import type {
  GalleryConfig,
  GalleryContextValue,
  GalleryItem,
  MediaType,
} from "./types";

export const GalleryCtx = React.createContext<GalleryContextValue | null>(null);

export function useGallery(): GalleryContextValue {
  const ctx = React.useContext(GalleryCtx);
  if (!ctx) throw new Error("useGallery must be used inside GalleryRoot");
  return ctx;
}

export interface GalleryProviderProps {
  items: GalleryItem[];
  onReorder?: (items: GalleryItem[]) => void;
  onSelect?: (selectedIds: string[]) => void;
  config?: GalleryConfig;
  children?: React.ReactNode;
  className?: string;
}

export function GalleryProvider({
  children,
  config = {},
  items: itemsProp,
  onReorder,
  onSelect,
}: GalleryProviderProps) {
  const [items, setItems] = React.useState<GalleryItem[]>(itemsProp);
  const [selectedIds, setSelectedIds] = React.useState<Set<string>>(new Set());
  const [lightboxId, setLightboxId] = React.useState<string | null>(null);
  const [filter, setFilter] = React.useState<MediaType | "all">("all");

  React.useEffect(() => {
    setItems(itemsProp);
  }, [itemsProp]);

  const filteredItems =
    filter === "all" ? items : items.filter((i) => i.type === filter);

  const lightboxItems = filteredItems.filter(
    (i) => i.type === "image" || i.type === "video",
  );

  const select = React.useCallback(
    (id: string, multi = false) => {
      const mode = config.selectionMode ?? "single";
      if (mode === "none") return;

      setSelectedIds((prev) => {
        if (mode === "single") return new Set([id]);
        if (multi && mode === "multi") {
          const next = new Set(prev);
          if (next.has(id)) next.delete(id);
          else next.add(id);
          return next;
        }
        return new Set([id]);
      });
    },
    [config.selectionMode],
  );

  const deselect = React.useCallback((id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  }, []);

  const selectAll = React.useCallback(() => {
    setSelectedIds(new Set(filteredItems.map((i) => i.id)));
  }, [filteredItems]);

  const clearSelection = React.useCallback(() => {
    setSelectedIds(new Set());
  }, []);

  const openLightbox = React.useCallback((id: string) => {
    setLightboxId(id);
  }, []);

  const closeLightbox = React.useCallback(() => {
    setLightboxId(null);
  }, []);

  const nextLightbox = React.useCallback(() => {
    setLightboxId((prev) => {
      if (!prev) return null;
      const idx = lightboxItems.findIndex((i) => i.id === prev);
      const next = lightboxItems[(idx + 1) % lightboxItems.length];
      return next?.id ?? prev;
    });
  }, [lightboxItems]);

  const prevLightbox = React.useCallback(() => {
    setLightboxId((prev) => {
      if (!prev) return null;
      const idx = lightboxItems.findIndex((i) => i.id === prev);
      const next =
        lightboxItems[(idx - 1 + lightboxItems.length) % lightboxItems.length];
      return next?.id ?? prev;
    });
  }, [lightboxItems]);

  const reorder = React.useCallback(
    (next: GalleryItem[]) => {
      setItems(next);
      onReorder?.(next);
    },
    [onReorder],
  );

  React.useEffect(() => {
    onSelect?.(Array.from(selectedIds));
  }, [selectedIds]);

  return (
    <GalleryCtx.Provider
      value={{
        items: filteredItems,
        selectedIds,
        lightboxId,
        filter,
        config,
        select,
        deselect,
        selectAll,
        clearSelection,
        openLightbox,
        closeLightbox,
        nextLightbox,
        prevLightbox,
        setFilter,
        reorder,
      }}
    >
      {children}
    </GalleryCtx.Provider>
  );
}

import * as React from "react";
import { GalleryProvider, GalleryProviderProps } from "./gallery-context";
import { GalleryGrid } from "./gallery-grid";
import { GalleryToolbar } from "./gallery-toolbar";
import { GalleryLightbox } from "./gallery-lightbox";
import { cn } from "@/lib/utils";

export interface GalleryRootProps extends GalleryProviderProps {
  children?: React.ReactNode;
}

export function GalleryRoot({ children, ...providerProps }: GalleryRootProps) {
  return (
    <GalleryProvider {...providerProps}>
      {children ?? (
        <div className={cn("flex flex-col gap-3", providerProps.className)}>
          <GalleryToolbar />
          <GalleryGrid />
          <GalleryLightbox />
        </div>
      )}
    </GalleryProvider>
  );
}

GalleryRoot.displayName = "GalleryRoot";

import { useGallery } from "./gallery-context";
import { GalleryItemCard } from "./gallery-item";
import { SortableRoot, SortableItem } from "../sortable";
import { cn } from "@/lib/utils";

export interface GalleryGridProps {
  className?: string;
}

export function GalleryGrid({ className }: GalleryGridProps) {
  const { items, config, reorder } = useGallery();
  const cols = config.columns ?? 4;

  const grid = (
    <div
      className={cn("grid gap-2", className)}
      style={{
        gridTemplateColumns: config.columns
          ? `repeat(${cols}, minmax(0, 1fr))`
          : "repeat(auto-fill, minmax(120px, 1fr))",
      }}
    >
      {items.map((item) =>
        config.sortable ? (
          <SortableItem key={item.id} id={item.id}>
            <GalleryItemCard item={item} className="w-full" />
          </SortableItem>
        ) : (
          <GalleryItemCard key={item.id} item={item} />
        ),
      )}
    </div>
  );

  if (!config.sortable) return grid;

  return (
    <SortableRoot
      config={{
        layout: "grid",
      }}
      items={items}
      onReorder={reorder}
    >
      {grid}
    </SortableRoot>
  );
}

GalleryGrid.displayName = "GalleryGrid";

import * as React from "react";
import { useGallery } from "./gallery-context";
import {
  IconPhoto,
  IconVideo,
  IconMusic,
  IconFileText,
  IconFile,
  IconCheckbox,
  IconX,
} from "@tabler/icons-react";
import type { MediaType } from "./types";
import { Button } from "@/components/ui/button";

const FILTERS: {
  label: string;
  value: MediaType | "all";
  icon: React.ElementType;
}[] = [
  { label: "All", value: "all", icon: IconFile },
  { label: "Images", value: "image", icon: IconPhoto },
  { label: "Video", value: "video", icon: IconVideo },
  { label: "Audio", value: "audio", icon: IconMusic },
  { label: "Docs", value: "document", icon: IconFileText },
];

type ToolbarButtonProps = React.ComponentPropsWithoutRef<typeof Button>;

function ToolbarButton({
  variant = "ghost",
  size = "sm",
  children,
  ...props
}: ToolbarButtonProps) {
  return (
    <Button variant={variant} size={size} {...props}>
      {children}
    </Button>
  );
}

export function GalleryToolbar() {
  const {
    filter,
    setFilter,
    selectedIds,
    items,
    selectAll,
    clearSelection,
    config,
  } = useGallery();
  const hasSelection = selectedIds.size > 0;
  const mode = config.selectionMode ?? "single";

  return (
    <div className="flex items-center flex-wrap justify-between gap-3">
      <div className="flex items-center overflow-x-auto gap-1 p-1 rounded-lg border border-border bg-card/80 w-fit">
        {FILTERS.map(({ label, value, icon: Icon }) => (
          <ToolbarButton
            key={value}
            onClick={() => setFilter(value)}
            variant={filter === value ? "default" : "ghost"}
          >
            <Icon size={12} strokeWidth={2} />
            {label}
          </ToolbarButton>
        ))}
      </div>

      {mode === "multi" && (
        <div className="flex items-center gap-2">
          {hasSelection && (
            <span className="text-[11px] text-muted-foreground">
              {selectedIds.size} selected
            </span>
          )}
          <ToolbarButton
            onClick={hasSelection ? clearSelection : selectAll}
            variant="outline"
          >
            {hasSelection ? (
              <>
                <IconX size={12} /> Clear
              </>
            ) : (
              <>
                <IconCheckbox size={12} /> Select all
              </>
            )}
          </ToolbarButton>
        </div>
      )}

      <span className="text-[11px] text-muted-foreground ml-auto">
        {items.length} item{items.length !== 1 ? "s" : ""}
      </span>
    </div>
  );
}

GalleryToolbar.displayName = "GalleryToolbar";

import * as React from "react";
import { useGallery } from "./gallery-context";
import { cn } from "@/lib/utils";
import {
  IconX,
  IconChevronLeft,
  IconChevronRight,
  IconDownload,
} from "@tabler/icons-react";

export function GalleryLightbox() {
  const { items, lightboxId, closeLightbox, nextLightbox, prevLightbox } =
    useGallery();
  const item = items.find((i) => i.id === lightboxId);

  React.useEffect(() => {
    if (!lightboxId) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") closeLightbox();
      if (e.key === "ArrowRight") nextLightbox();
      if (e.key === "ArrowLeft") prevLightbox();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [lightboxId, closeLightbox, nextLightbox, prevLightbox]);

  if (!lightboxId || !item) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm"
      onClick={closeLightbox}
    >
      <div className="absolute top-4 right-4 flex items-center gap-2 z-10">
        <a
          href={item.url}
          download={item.name}
          onClick={(e) => e.stopPropagation()}
          className="w-8 h-8 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 text-white transition-colors"
        >
          <IconDownload size={15} />
        </a>
        <button
          onClick={closeLightbox}
          className="w-8 h-8 flex items-center justify-center rounded-lg bg-white/10 hover:bg-white/20 text-white transition-colors"
        >
          <IconX size={15} />
        </button>
      </div>

      <button
        onClick={(e) => {
          e.stopPropagation();
          prevLightbox();
        }}
        className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors"
      >
        <IconChevronLeft size={20} />
      </button>
      <button
        onClick={(e) => {
          e.stopPropagation();
          nextLightbox();
        }}
        className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors"
      >
        <IconChevronRight size={20} />
      </button>

      <div
        className="relative max-w-[90vw] max-h-[85vh] flex items-center justify-center"
        onClick={(e) => e.stopPropagation()}
      >
        {item.type === "image" && (
          <img
            src={item.url}
            alt={item.name}
            className="max-w-full max-h-[85vh] rounded-lg object-contain shadow-2xl"
          />
        )}
        {item.type === "video" && (
          <video
            src={item.url}
            controls
            autoPlay
            className="max-w-full max-h-[85vh] rounded-lg shadow-2xl"
          />
        )}

        <div className="absolute -bottom-8 left-0 right-0 text-center">
          <p className="text-[11px] text-white/60 truncate">{item.name}</p>
        </div>
      </div>
    </div>
  );
}

GalleryLightbox.displayName = "GalleryLightbox";

export { GalleryRoot } from "./gallery-root";
export { GalleryGrid } from "./gallery-grid";
export { GalleryItemCard } from "./gallery-item";
export { GalleryLightbox } from "./gallery-lightbox";
export { GalleryToolbar } from "./gallery-toolbar";
export { useGallery } from "./gallery-context";
export type { GalleryItem, GalleryConfig, MediaType } from "./types";
